-- =============================================================================
-- MATCHING THE FOREIGN-KEY CONVENTION
--
-- 20260826220000 wrote `clinical_document`'s foreign keys inline in the CREATE
-- TABLE with no ON UPDATE clause, which Postgres reads as NO ACTION. Every other
-- table in this schema was generated by Prisma, which emits ON UPDATE CASCADE,
-- and `migrate:check` therefore reported drift: the same three keys, described
-- differently.
--
-- Nothing about behaviour changes. Primary keys here are uuidv7 and are never
-- updated, so CASCADE and NO ACTION are indistinguishable in practice. What
-- changes is that the schema and the migrations agree again — and a drift check
-- that is routinely red stops being read, which is the actual cost.
--
-- Written as a new migration rather than an edit to the applied one: Prisma
-- records a checksum per migration, and editing one that has already run makes
-- `migrate dev` refuse to work on every machine that had it.
-- =============================================================================

ALTER TABLE "clinical_document" DROP CONSTRAINT "clinical_document_tenant_fkey";
ALTER TABLE "clinical_document" DROP CONSTRAINT "clinical_document_patient_fkey";
ALTER TABLE "clinical_document" DROP CONSTRAINT "clinical_document_uploader_fkey";

ALTER TABLE "clinical_document" ADD CONSTRAINT "clinical_document_tenant_fkey"
  FOREIGN KEY ("tenant_id") REFERENCES "tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "clinical_document" ADD CONSTRAINT "clinical_document_patient_fkey"
  FOREIGN KEY ("patient_id") REFERENCES "patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "clinical_document" ADD CONSTRAINT "clinical_document_uploader_fkey"
  FOREIGN KEY ("uploaded_by_user_id") REFERENCES "app_user"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
